const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: 'The Global Burden of Mental Illness' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Left panel
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 4.2, h: 5.625,
    fill: { color: theme.primary }
  });

  // Accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.2, y: 0, w: 0.06, h: 5.625,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("The Global\nBurden of\nMental Illness", {
    x: 0.5, y: 0.7, w: 3.4, h: 2.6,
    fontSize: 34, fontFace: "Georgia",
    color: "FFFFFF", bold: true, margin: 0
  });

  // Subtitle
  slide.addText("Prevalence, Impact, and\nthe Treatment Gap", {
    x: 0.5, y: 3.5, w: 3.4, h: 0.9,
    fontSize: 16, fontFace: "Calibri",
    color: theme.light, margin: 0
  });

  // Year badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 4.6, w: 1.2, h: 0.35,
    fill: { color: theme.accent }, rectRadius: 0.15
  });
  slide.addText("2023 Data", {
    x: 0.5, y: 4.6, w: 1.2, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Decorative circles on right
  slide.addShape(pres.shapes.OVAL, {
    x: 6.2, y: 0.8, w: 3.0, h: 3.0,
    fill: { color: theme.secondary, transparency: 30 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 7.2, y: 2.0, w: 2.2, h: 2.2,
    fill: { color: theme.accent, transparency: 40 }
  });

  // Source attribution
  slide.addText("Data: IHME, Global Burden of Disease (2025) | Our World in Data", {
    x: 4.6, y: 4.8, w: 5.0, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: theme.primary, margin: 0
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "006d77", secondary: "83c5be", accent: "e29578", light: "ffddd2", bg: "edf6f9" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

