const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 4, title: 'Depression and Anxiety Carry Nearly Equal Burden' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Depression and Anxiety Carry Nearly Equal Disease Burden", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  const barMaxH = 2.8;
  const barW = 2.2;
  const barY = 1.5;
  const depH = barMaxH;
  const anxH = barMaxH * (686.5 / 694.6);

  // Depression bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 2.0, y: barY + (barMaxH - depH), w: barW, h: depH,
    fill: { color: theme.accent }
  });
  slide.addText("694.6", {
    x: 2.0, y: barY - 0.55, w: barW, h: 0.5,
    fontSize: 36, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "center", valign: "middle", margin: 0
  });
  slide.addText("Depressive\nDisorders", {
    x: 2.0, y: barY + barMaxH + 0.1, w: barW, h: 0.55,
    fontSize: 13, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center", valign: "top", margin: 0
  });

  // Anxiety bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: barY + (barMaxH - anxH), w: barW, h: anxH,
    fill: { color: theme.primary }
  });
  slide.addText("686.5", {
    x: 5.8, y: barY - 0.55, w: barW, h: 0.5,
    fontSize: 36, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "center", valign: "middle", margin: 0
  });
  slide.addText("Anxiety\nDisorders", {
    x: 5.8, y: barY + barMaxH + 0.1, w: barW, h: 0.55,
    fontSize: 13, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center", valign: "top", margin: 0
  });

  // Callout box
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 4.7, w: 5.5, h: 0.5,
    fill: { color: theme.light }, rectRadius: 0.08
  });
  slide.addText("Together they account for ~80% of total mental health DALYs", {
    x: 0.6, y: 4.7, w: 5.3, h: 0.5,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, valign: "middle", margin: 0
  });

  // DALYs label
  slide.addText("DALYs per 100,000", {
    x: 0.3, y: 2.5, w: 1.4, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, align: "center", margin: 0,
    rotate: 270
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "006d77", secondary: "83c5be", accent: "e29578", light: "ffddd2", bg: "edf6f9" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

