const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 5, title: 'Schizophrenia and Bipolar Disorder' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText("Lower Prevalence but Severe Individual Impact", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 26, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0
  });

  // Subtitle
  slide.addText("Schizophrenia and bipolar disorder affect fewer people, but carry disproportionately high individual burden", {
    x: 0.5, y: 0.95, w: 9, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });

  // Schizophrenia card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.7, w: 4.3, h: 2.8,
    fill: { color: theme.bg }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.7, w: 4.3, h: 0.06,
    fill: { color: theme.accent }
  });
  slide.addText("210.2", {
    x: 0.7, y: 1.95, w: 3.9, h: 1.0,
    fontSize: 52, fontFace: "Georgia",
    color: theme.accent, bold: true, margin: 0
  });
  slide.addText("DALYs per 100,000", {
    x: 0.7, y: 2.85, w: 3.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });
  slide.addText("Schizophrenia", {
    x: 0.7, y: 3.3, w: 3.9, h: 0.4,
    fontSize: 20, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0
  });
  slide.addText("Reflects severe disability associated with the condition despite lower population prevalence", {
    x: 0.7, y: 3.75, w: 3.8, h: 0.55,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });

  // Bipolar card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.7, w: 4.3, h: 2.8,
    fill: { color: theme.bg }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.7, w: 4.3, h: 0.06,
    fill: { color: theme.primary }
  });
  slide.addText("94.6", {
    x: 5.4, y: 1.95, w: 3.9, h: 1.0,
    fontSize: 52, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0
  });
  slide.addText("DALYs per 100,000", {
    x: 5.4, y: 2.85, w: 3.9, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });
  slide.addText("Bipolar Disorder", {
    x: 5.4, y: 3.3, w: 3.9, h: 0.4,
    fontSize: 20, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0
  });
  slide.addText("A smaller but meaningful share of the total burden, with significant impact on quality of life", {
    x: 5.4, y: 3.75, w: 3.8, h: 0.55,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });

  // Context bar at bottom
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.8, w: 9.0, h: 0.45,
    fill: { color: theme.light, transparency: 50 }
  });
  slide.addText("For comparison: depressive disorders = 694.6 | anxiety disorders = 686.5 DALYs per 100,000", {
    x: 0.7, y: 4.8, w: 8.6, h: 0.45,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, valign: "middle", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "006d77", secondary: "83c5be", accent: "e29578", light: "ffddd2", bg: "edf6f9" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

