const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 6, title: 'The Treatment Gap' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Treatment Is Available but Often Lacking or Poor Quality", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  // Intro text
  slide.addText("Mental illnesses are treatable and their impact can be reduced. Yet significant barriers persist:", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });

  const barriers = [
    { icon: "S", label: "Stigma", desc: "Many people are uncomfortable disclosing symptoms to healthcare professionals or even to people they know" },
    { icon: "A", label: "Access", desc: "Treatment is often lacking, especially in low- and middle-income countries" },
    { icon: "Q", label: "Quality", desc: "Even where treatment exists, it may be of poor quality" },
    { icon: "U", label: "Underreporting", desc: "Discomfort with disclosure makes it difficult to estimate the true prevalence of mental illnesses" }
  ];

  const cols = 2;
  const cardW = 4.2;
  const cardH = 1.6;
  const startX = 0.5;
  const startY = 1.65;
  const gapX = 0.6;
  const gapY = 0.3;

  barriers.forEach((b, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const cx = startX + col * (cardW + gapX);
    const cy = startY + row * (cardH + gapY);

    // Card bg
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: "FFFFFF" }, rectRadius: 0.1
    });

    // Icon circle
    slide.addShape(pres.shapes.OVAL, {
      x: cx + 0.2, y: cy + 0.25, w: 0.55, h: 0.55,
      fill: { color: theme.accent }
    });
    slide.addText(b.icon, {
      x: cx + 0.2, y: cy + 0.25, w: 0.55, h: 0.55,
      fontSize: 18, fontFace: "Georgia",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    // Label
    slide.addText(b.label, {
      x: cx + 0.95, y: cy + 0.2, w: 3.0, h: 0.35,
      fontSize: 16, fontFace: "Georgia",
      color: theme.primary, bold: true, margin: 0
    });

    // Description
    slide.addText(b.desc, {
      x: cx + 0.95, y: cy + 0.6, w: 3.0, h: 0.85,
      fontSize: 11, fontFace: "Calibri",
      color: theme.secondary, margin: 0
    });
  });

  // Bottom note
  slide.addText("The true burden of mental illness is likely higher than reported figures suggest.", {
    x: 0.5, y: 4.9, w: 8.0, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: theme.accent, italic: true, margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "006d77", secondary: "83c5be", accent: "e29578", light: "ffddd2", bg: "edf6f9" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

