const pptxgen = require("pptxgenjs");
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Public Health Analytics";
pres.title = "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap";

const theme = {
  primary: "006d77",
  secondary: "83c5be",
  accent: "e29578",
  light: "ffddd2",
  bg: "edf6f9"
};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, "0");
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: "./output/presentation.pptx" })
  .then(() => console.log("Presentation saved to ./output/presentation.pptx"))
  .catch(err => console.error("Error:", err));

